// Shared scaffolding for the per-feature live modules.
//
// Everything here exists so a feature test can start from a REAL vehicle that is
// already published, without hand-writing SQL. Setup goes through the app's own
// authenticated API with a real browser session; the action under test in each
// F*.mjs module is still driven through the UI.
//
// Fixture documents are generated by the project's own generator
// (frontend/qa/fixtures/make_docs.py) so they carry a real PDF text layer that
// the production PyMuPDF/RapidOCR pipeline can genuinely read. They are labelled
// QA documents, not forged certificates.
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { ROOT, BASE, api, sqlOne, uiUpload } from "./harness.mjs";
export { uiUpload, until } from "./harness.mjs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
export const TMP = path.join(__dirname, "files");
fs.mkdirSync(TMP, { recursive: true });

const PY = path.join(ROOT, "backend", ".venv", "Scripts", "python.exe");
const FIXTURES = path.join(ROOT, "frontend", "qa", "fixtures");
const DOCGEN = path.join(FIXTURES, "make_docs.py");
export const PHOTOS = ["photo-front.jpg", "photo-side.jpg", "photo-interior.jpg"]
  .map((n) => path.join(FIXTURES, n))
  .filter((p) => fs.existsSync(p));

// Category facts used to pick legal identifiers and powertrain fields.
export const CATS = {
  petrol_motorcycle: { twoWheeler: true, electric: false, label: "Petrol Motorcycle", make: "Royal Enfield", model: "Classic 350", km: 18500, price: 165000 },
  petrol_scooter: { twoWheeler: true, electric: false, label: "Petrol Scooter", make: "Honda", model: "Activa 6G", km: 9200, price: 92000 },
  electric_scooter: { twoWheeler: true, electric: true, label: "Electric Scooter", make: "Ola", model: "S1 Pro", km: 6400, price: 128000, soh: 92 },
  electric_motorcycle: { twoWheeler: true, electric: true, label: "Electric Motorcycle", make: "Revolt", model: "RV400", km: 11200, price: 149000, soh: 88 },
  passenger_car: { twoWheeler: false, electric: false, label: "Petrol Car", make: "Hyundai", model: "i20", km: 45000, price: 675000 },
  electric_car: { twoWheeler: false, electric: true, label: "Electric Car", make: "Tata", model: "Nexon EV", km: 28000, price: 1395000, soh: 95 },
};

const VIN_ALPHABET = "ABCDEFGHJKLMNPRSTUVWXYZ0123456789"; // ISO 3779: no I, O or Q.
const ALNUM = "ABCDEFGHJKLMNPRSTUVWXYZ0123456789";

function digits(n, len) {
  return String(n).padStart(len, "0").slice(-len);
}

/** A registration number that is not already in the shared database. */
export function uniqueReg(index = 0) {
  for (let n = 0; n < 600; n += 1) {
    const reg = `MH${digits(12 + (index % 8), 2)}QA${digits(Date.now() % 9000 + index * 131 + n * 17, 4)}`;
    if (!sqlOne("SELECT id FROM vehicles WHERE reg_no = ?", reg)) return reg;
  }
  throw new Error("could not allocate a unique registration number");
}

/**
 * A primary identifier in the shape the category actually requires:
 * 17 characters for a car, 8-22 for a two-wheeler frame/chassis number.
 */
export function uniqueIdentifier(catId, index = 0) {
  const twoWheeler = CATS[catId]?.twoWheeler ?? true;
  for (let n = 0; n < 600; n += 1) {
    const seed = Date.now() + index * 977 + n * 31;
    let value;
    if (twoWheeler) value = `FRM${digits(seed % 1_000_000_000_000, 12)}${digits(index, 2)}`;
    else {
      value = "M";
      for (let i = 1; i < 17; i += 1) value += VIN_ALPHABET[(seed * (i + 7) + i * 13) % VIN_ALPHABET.length];
    }
    if (!sqlOne("SELECT id FROM vehicles WHERE vin = ?", value)) return value;
  }
  throw new Error("could not allocate a unique primary identifier");
}

function randomPowertrainId(catId, index, salt) {
  const twoWheeler = CATS[catId]?.twoWheeler ?? true;
  let out = "";
  const pool = twoWheeler ? ALNUM : VIN_ALPHABET;
  const len = twoWheeler ? 12 : 16;
  let s = (Date.now() >>> 3) + index * 613 + salt;
  for (let i = 0; i < len; i += 1) {
    s = (s * 1103515245 + 12345) & 0x7fffffff;
    out += pool[s % pool.length];
  }
  return out;
}

/**
 * Full identity for one test vehicle: unique reg + identifier, plus the
 * powertrain numbers the fixture document and the DB record should agree on.
 */
export function identity(catId, index = 0) {
  const cat = CATS[catId];
  if (!cat) throw new Error(`unknown category ${catId}`);
  return {
    catId,
    ...cat,
    year: 2022,
    regNo: uniqueReg(index),
    vin: uniqueIdentifier(catId, index),
    identifierLabel: cat.twoWheeler ? "Chassis / frame number" : "VIN (17 characters)",
    engineNumber: cat.electric ? null : randomPowertrainId(catId, index, 3),
    motorNumber: cat.electric ? randomPowertrainId(catId, index, 5) : null,
    batterySerial: cat.electric ? `BAT-${randomPowertrainId(catId, index, 9)}` : null,
  };
}

/** Generate a real text-layer PDF for a vehicle and return its path. */
export function makeDocPdf(ident, kind = "rc", name = null) {
  if (!fs.existsSync(PY)) throw new Error(`fixture generator python missing at ${PY}`);
  if (!fs.existsSync(DOCGEN)) throw new Error(`fixture generator missing at ${DOCGEN}`);
  const spec = {
    name: name ?? `${kind}-${ident.catId}-${Date.now().toString(36)}`,
    kind,
    reg: ident.regNo,
    identifier: ident.vin,
    identifier_label: ident.identifierLabel,
    make: ident.make,
    model: ident.model,
    year: ident.year,
    km: ident.km,
    engine_number: ident.engineNumber,
    motor_number: ident.motorNumber,
    battery_serial: ident.batterySerial,
    policy: `POL-${digits(Date.now() % 1_000_000, 6)}`,
    amount: "18,500",
  };
  const specFile = path.join(TMP, `${spec.name}.json`);
  fs.writeFileSync(specFile, JSON.stringify([spec]));
  execFileSync(PY, [DOCGEN, "--spec", specFile, "--out", TMP], { stdio: "pipe" });
  const pdf = path.join(TMP, `${spec.name}.pdf`);
  if (!fs.existsSync(pdf)) throw new Error(`fixture generator produced no ${pdf}`);
  return pdf;
}

const b64 = (p) => fs.readFileSync(p).toString("base64");

/**
 * Create a vehicle through the seller API and satisfy every publish blocker
 * with real uploads (3 photos + an RC document the OCR pipeline can read).
 * Returns null plus the raw error when the app refuses, so a test can report
 * a BLOCKED prerequisite instead of silently continuing.
 */
export async function publishedVehicle(page, catId, index = 0, extra = {}) {
  const ident = identity(catId, index);
  const specs = {
    ...(ident.electric
      ? { motor_number: ident.motorNumber, battery_serial: ident.batterySerial, battery_soh: ident.soh, battery_capacity_kwh: 35 }
      : { engine_number: ident.engineNumber, engine_cc: ident.twoWheeler ? 349 : 1197 }),
    ...extra.specs,
  };
  const create = await api(page, "POST", "/api/v1/seller/vehicles", {
    make: ident.make,
    model: ident.model,
    year: ident.year,
    regNo: ident.regNo,
    vin: ident.vin,
    fuel: ident.electric ? "Electric" : "Petrol",
    transmission: ident.electric ? "Direct drive" : "Manual",
    category: ident.label,
    categoryId: catId,
    condition: "Good",
    color: "QA Graphite",
    location: "Pune, Maharashtra",
    ownershipCount: 1,
    price: ident.price,
    km: ident.km,
    description: "TrustDrive live functional audit vehicle.",
    specs,
  });
  const vehicleId = create.json?.data?.id ?? null;
  const listingId = create.json?.data?.listingId ?? null;
  const out = { ident, vehicleId, listingId, create, photos: null, rc: null, publish: null, ready: false, blocked: null };
  if (!vehicleId) {
    out.blocked = `draft not created: HTTP ${create.status} ${create.json?.error?.code ?? ""} ${create.json?.error?.message ?? ""}`;
    return out;
  }

  if (!PHOTOS.length) {
    out.blocked = "no fixture photographs available on disk";
    return out;
  }
  out.photos = await uiUpload(
    page,
    `/api/v1/vehicles/${vehicleId}/photos`,
    {},
    PHOTOS.slice(0, 3).map((p) => ({ field: "files", name: path.basename(p), type: "image/jpeg", b64: b64(p) }))
  );

  const rcType = ident.twoWheeler ? "rc_2w" : "rc";
  const pdf = makeDocPdf(ident, "rc");
  out.rc = await uiUpload(page, `/api/v1/vehicles/${vehicleId}/documents`, { type: rcType, consent: "true" }, [
    { field: "file", name: path.basename(pdf), type: "application/pdf", b64: b64(pdf) },
  ]);
  out.rcType = rcType;
  out.rcPath = pdf;
  out.documentStatus = out.rc.json?.data?.ocr?.documentStatus ?? null;

  out.publish = await api(page, "POST", `/api/v1/seller/listings/${listingId}/publish`, {});
  out.ready = out.publish?.status === 200;
  if (!out.ready) {
    out.blocked = `publish HTTP ${out.publish?.status} ${out.publish?.json?.error?.code ?? ""} ` +
      JSON.stringify(out.publish?.json?.error?.details ?? {}).slice(0, 300);
  }
  return out;
}

export const errText = (res) =>
  `HTTP ${res?.status} ${res?.json?.error?.code ?? ""}: ${res?.json?.error?.message ?? String(res?.text ?? "").slice(0, 160)}`;

export { BASE, ROOT };
